message.content:
{
  "title": "The Mirror Bridge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers arrive at the ruined city gates.",
      "visual_description": "A massive iron gate hangs crookedly between cracked stone pillars. Mara the Cartographer studies a torn map while the Glass Diver peers through his helmet at the dark archway ahead. The Oracle Lamp flickers on a broken cart, casting long shadows.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The Tin Fox scouts ahead through rubble.",
      "visual_description": "The small clockwork fox picks its way over fallen blocks of masonry. Its key-wind tail glints in the pale light. Mara and the Glass Diver follow at a cautious distance.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "They find the Sleeping Tax Collector dozing on a pile of ledgers.",
      "visual_description": "In a half-collapsed courtyard, a man in a dusty coat naps on a stack of stamped papers and heavy ledgers. His head rests on a book. The Oracle Lamp's eye glows irritably.",
      "characters": ["sleeping_tax_collector", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye pulses red as it speaks. Beyond the courtyard, a twisted spire rises against a bruised sky. Mara traces a route on her map with a trembling finger.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The Glass Diver peers into a reflective puddle to see inside the tower.",
      "visual_description": "Kneeling beside a rain-filled crater, the Glass Diver lowers his helmet toward the water. His reflection shifts, revealing a dim room with a tall mirror inside the tower.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara confirms their path through a magic door.",
      "visual_description": "At the base of the tower stands a door carved with shifting runes. Mara holds her compass close; the needle spins and then points straight at the door.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Tin Fox slips through a crack and unlocks the magic door from inside.",
      "visual_description": "The small metal fox squeezes through a narrow gap in the stonework. Inside, it bites a hidden lever, and the rune-carved door groans open.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "They ascend the cursed tower's spiral staircase.",
      "visual_description": "The stairway winds upward, its stones slick with damp. Mara leads, one hand on the wall. The Oracle Lamp's light reveals strange symbols scratched into the walls.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector is left behind, still snoring.",
      "visual_description": "At a landing, the tax collector is propped against a barrel, ledger pages scattered around him. The group moves on without waking him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver swims through a mirror into a hidden chamber.",
      "visual_description": "At the tower's top, a tall silver mirror stands against the wall. The Glass Diver touches its surface and steps through, ripples spreading across the glass.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the mirror chamber, they find the person they came to rescue.",
      "visual_description": "A dim room with mirrored walls reflects infinite copies of the group. At the center, a figure sits on a stone bench, dazed. Mara rushes forward.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp reveals the exit is through a series of refracted doorways.",
      "visual_description": "The lamp's flame eye projects a beam onto one mirror, which reflects to another, showing a chain of shimmering portals leading downward.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "They descend through the mirrored passages, guided by the Tin Fox.",
      "visual_description": "The clockwork fox dashes ahead, its blue eyes leaving trails of light that align with the reflections. The group follows, stepping from mirror to mirror.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The Sleeping Tax Collector stirs and accidentally blocks a door.",
      "visual_description": "Reaching a lower level, they find the tax collector has rolled over in his sleep, his back against a narrow doorway. Mara sighs and steps over him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "They emerge onto a balcony overlooking the escape bridge.",
      "visual_description": "A stone balcony juts out over a chasm. Below, a narrow suspension bridge connects to the outer city wall, its ropes frayed but intact.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols appear on the bridge, but they are illusions from the tower.",
      "visual_description": "Across the bridge, shapes in armor march back and forth. The Oracle Lamp's light flickers, and the shapes waver like heat mirages—mere reflections from the cursed tower.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver shatters the illusion by diving through a puddle on the bridge.",
      "visual_description": "The Glass Diver kneels and presses his helmet into a shallow puddle of rainwater. The surface ripples outward, and the armored shapes dissolve into mist.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge to freedom as the old royal banners flutter.",
      "visual_description": "The group hurries across the swaying bridge. Faded banners bearing a lost city's crest snap in the wind. Mara looks back once, then forward to the open road.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "LFpiTRpDnbkVVP3Y0ZmHpA"
}

